# Let me analyze character mappings and potential replacements
inputs = ['wkiwi', 'jvu', 'wy', 'videw', 'kk']
outputs = ['axyfgaxyiaxyi', 'fgaxyfyhvu', 'axyy', 'videaxy', 'fgaxyfgaxy']

# Look for common patterns and character substitutions
print("Detailed analysis:")

# Check if 'y' maps to something specific
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {out}")
    # Check if 'y' appears in input or output
    if 'y' in inp:
        print(f"  Input contains 'y'")
    if 'y' in out:
        print(f"  Output contains 'y'")
    print()

# Check for potential multi-character patterns
print("Checking for multi-character patterns:")
patterns = set()
for inp in inputs:
    for i in range(len(inp)):
        for j in range(i+1, len(inp)+1):
            patterns.add(inp[i:j])

for out in outputs:
    for i in range(len(out)):
        for j in range(i+1, len(out)+1):
            patterns.add(out[i:j])

print(f"Found {len(patterns)} unique patterns")

